transferVelocities(toGrid, flipRatio) {
  const n = this.fNumY, h = this.h, h1 = this.fInvSpacing, h2 = 0.5 * h;
  if (toGrid) {
    this.u.fill(0); this.v.fill(0); this.du.fill(0); this.dv.fill(0);
    for (let i = 0; i < this.fNumCells; i++)
      this.cellType[i] = this.s[i] === 0 ? SOLID : AIR;
    for (let i = 0; i < this.numParticles; i++) {
      const xi = clamp(Math.floor(this.pos[2*i]   * h1), 0, this.fNumX - 1);
      const yi = clamp(Math.floor(this.pos[2*i+1] * h1), 0, this.fNumY - 1);
      const c = xi * n + yi;
      if (this.cellType[c] === AIR) this.cellType[c] = FLUID;
    }
  } else {
    this.turb.fill(0);
  }

  for (let comp = 0; comp < 2; comp++) {
    // staggered MAC grid: u lives on vertical faces, v on horizontal faces
    const dx = comp === 0 ? 0 : h2;
    const dy = comp === 0 ? h2 : 0;
    const f = comp === 0 ? this.u : this.v;
    const prevF = comp === 0 ? this.prevU : this.prevV;
    const dArr = comp === 0 ? this.du : this.dv;
    const offset = comp === 0 ? n : 1;

    for (let i = 0; i < this.numParticles; i++) {
      const x = clamp(this.pos[2*i],   h, (this.fNumX - 1) * h);
      const y = clamp(this.pos[2*i+1], h, (this.fNumY - 1) * h);
      const x0 = Math.min(Math.floor((x - dx) * h1), this.fNumX - 2);
      const tx = ((x - dx) - x0 * h) * h1;
      const x1 = Math.min(x0 + 1, this.fNumX - 2);
      const y0 = Math.min(Math.floor((y - dy) * h1), this.fNumY - 2);
      const ty = ((y - dy) - y0 * h) * h1;
      const y1 = Math.min(y0 + 1, this.fNumY - 2);
      const sx = 1 - tx, sy = 1 - ty;
      const d0 = sx*sy, d1 = tx*sy, d2 = tx*ty, d3 = sx*ty;
      const nr0 = x0*n + y0, nr1 = x1*n + y0, nr2 = x1*n + y1, nr3 = x0*n + y1;

      if (toGrid) {
        const pv = this.vel[2*i + comp];
        f[nr0] += pv*d0; dArr[nr0] += d0;
        f[nr1] += pv*d1; dArr[nr1] += d1;
        f[nr2] += pv*d2; dArr[nr2] += d2;
        f[nr3] += pv*d3; dArr[nr3] += d3;
      } else {
        // only sample faces that touch at least one non-air cell
        const v0 = (this.cellType[nr0] !== AIR || this.cellType[nr0 - offset] !== AIR) ? 1 : 0;
        const v1 = (this.cellType[nr1] !== AIR || this.cellType[nr1 - offset] !== AIR) ? 1 : 0;
        const v2 = (this.cellType[nr2] !== AIR || this.cellType[nr2 - offset] !== AIR) ? 1 : 0;
        const v3 = (this.cellType[nr3] !== AIR || this.cellType[nr3 - offset] !== AIR) ? 1 : 0;
        const dsum = v0*d0 + v1*d1 + v2*d2 + v3*d3;
        if (dsum > 0) {
          const picV = (v0*d0*f[nr0] + v1*d1*f[nr1] + v2*d2*f[nr2] + v3*d3*f[nr3]) / dsum;
          const corr = (v0*d0*(f[nr0]-prevF[nr0]) + v1*d1*(f[nr1]-prevF[nr1])
                      + v2*d2*(f[nr2]-prevF[nr2]) + v3*d3*(f[nr3]-prevF[nr3])) / dsum;
          const flipV = this.vel[2*i + comp] + corr;
          this.vel[2*i + comp] = (1 - flipRatio) * picV + flipRatio * flipV;
          this.turb[i] += Math.abs(flipV - picV);   // velocity deviation → whitewater
