transferVelocities(toGrid, flipRatio) {
  const n = this.fNumY, h = this.h, h1 = this.fInvSpacing, h2 = 0.5 * h;
  const nx = this.fNumX, ny = this.fNumY, np = this.numParticles;
  const pos = this.pos, vel = this.vel, cellType = this.cellType, turb = this.turb;
  const maxX = (nx - 1) * h, maxY = (ny - 1) * h;

  if (toGrid) {
    this.u.fill(0); this.v.fill(0); this.du.fill(0); this.dv.fill(0);
    const s = this.s;
    for (let i = 0; i < this.fNumCells; i++)
      cellType[i] = s[i] === 0 ? SOLID : AIR;
    for (let i = 0; i < np; i++) {
      const xi = clamp(Math.floor(pos[2*i]   * h1), 0, nx - 1);
      const yi = clamp(Math.floor(pos[2*i+1] * h1), 0, ny - 1);
      const c = xi * n + yi;
      if (cellType[c] === AIR) cellType[c] = FLUID;
    }
  } else {
    turb.fill(0);
  }

  for (let comp = 0; comp < 2; comp++) {
    // staggered MAC grid: u lives on vertical faces, v on horizontal faces
    const dx = comp === 0 ? 0 : h2;
    const dy = comp === 0 ? h2 : 0;
    const f = comp === 0 ? this.u : this.v;
    const prevF = comp === 0 ? this.prevU : this.prevV;
    const dArr = comp === 0 ? this.du : this.dv;
    const offset = comp === 0 ? n : 1;

    for (let i = 0; i < np; i++) {
      const x = clamp(pos[2*i],   h, maxX);
      const y = clamp(pos[2*i+1], h, maxY);
      const x0 = Math.min(Math.floor((x - dx) * h1), nx - 2);
      const tx = ((x - dx) - x0 * h) * h1;
      const x1 = Math.min(x0 + 1, nx - 2);
      const y0 = Math.min(Math.floor((y - dy) * h1), ny - 2);
      const ty = ((y - dy) - y0 * h) * h1;
      const y1 = Math.min(y0 + 1, ny - 2);
      const sx = 1 - tx, sy = 1 - ty;
      const d0 = sx*sy, d1 = tx*sy, d2 = tx*ty, d3 = sx*ty;
      const nr0 = x0*n + y0, nr1 = x1*n + y0, nr2 = x1*n + y1, nr3 = x0*n + y1;

      if (toGrid) {
        const pv = vel[2*i + comp];
        f[nr0] += pv*d0; dArr[nr0] += d0;
        f[nr1] += pv*d1; dArr[nr1] += d1;
        f[nr2] += pv*d2; dArr[nr2] += d2;
        f[nr3] += pv*d3; dArr[nr3] += d3;
      } else {
        // only sample faces that touch at least one non-air cell
        const v0 = (cellType[nr0] !== AIR || cellType[nr0 - offset] !== AIR) ? 1 : 0;
        const v1 = (cellType[nr1] !== AIR || cellType[nr1 - offset] !== AIR) ? 1 : 0;
        const v2 = (cellType[nr2] !== AIR || cellType[nr2 - offset] !== AIR) ? 1 : 0;
        const v3 = (cellType[nr3] !== AIR || cellType[nr3 - offset] !== AIR) ? 1 : 0;
        const dsum = v0*d0 + v1*d1 + v2*d2 + v3*d3;
        if (dsum > 0) {
          const picV = (v0*d0*f[nr0] + v1*d1*f[nr1] + v2*d2*f[nr2] + v3*d3*f[nr3]) / dsum;
          const corr = (v0*d0*(f[nr0]-prevF[nr0]) + v1*d1*(f[nr1]-prevF[nr1])
                      + v2*d2*(f[nr2]-prevF[nr2]) + v3*d3*(f[nr3]-prevF[nr3])) / dsum;
          const flipV = vel[2*i + comp] + corr;
          vel[2*i + comp] = (1 - flipRatio) * picV + flipRatio * flipV;
          turb[i] += Math.abs(flipV - picV);   // velocity deviation → whitewater
        }
      }
    }

    if (toGrid) {
      for (let i = 0; i < f.length; i++) if (dArr[i] > 0) f[i] /= dArr[i];
    }
  }

  if (toGrid) {
    // solid faces: enforce static-wall no-penetration (obstacle stamped after)
    const u = this.u, v = this.v;
    for (let i = 0; i < nx; i++) {
      const base = i * n;
      for (let j = 0; j < ny; j++) {
        const c = base + j;
        const solid = cellType[c] === SOLID;
        if (solid || (i > 0 && cellType[c - n] === SOLID)) u[c] = 0;
        if (solid || (j > 0 && cellType[c - 1] === SOLID)) v[c] = 0;
      }
    }
  }
}
